func generate(numRows int) [][]int {
	if numRows == 0 {
		return [][]int{}
	}
	res := [][]int{{1}}
	for len(res) < numRows {
		prev := res[len(res)-1]
		newRow := make([]int, len(prev)+1)
		newRow[0] = 1
		for i := 1; i < len(prev); i++ {
			newRow[i] = prev[i-1] + prev[i]
		}
		newRow[len(prev)] = 1
		res = append(res, newRow)
	}
	return res
}
